const raw = String($input.first().json.text || '');
const source = String($('Build master input').first().json.cv_text || '');
const chatId = String($('Build master input').first().json.chat_id);
let existing = [];
try { existing = $('Read existing master').all().map(i => i.json).filter(r => r.item_id); } catch (e) { existing = []; }

const fail = msg => [{ json: { _error: true, summary_text: msg } }];

// 1) Parse the model's answer
let m;
const s = raw.indexOf('{'), e = raw.lastIndexOf('}');
if (s < 0 || e <= s) return fail('I could not read the structure of that CV. Please try again, or paste it as text.');
try { m = JSON.parse(raw.slice(s, e + 1)); }
catch (err) { return fail('I could not read the structure of that CV. Please try again, or paste it as text.'); }

// 2) Helpers
const norm = x => String(x || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
const srcNorm = ' ' + norm(source) + ' ';
const srcNums = new Set((source.replace(/(\d),(?=\d{3}\b)/g, '$1').match(/\d+(?:[.,]\d+)?/g) || []).map(n => n.replace(',', '.')));
const numsOf = t => (String(t || '').replace(/(\d),(?=\d{3}\b)/g, '$1').match(/\d+(?:[.,]\d+)?/g) || []).map(n => n.replace(',', '.'));
const numbersOk = t => numsOf(t).every(n => srcNums.has(n));
const STOP = new Set(['and', 'the', 'of', 'for', 'de', 'la', 'le', 'des', 'du', 'et', 'at', 'in', 'x']);
const inSource = name => {
  const words = norm(name).split(' ').filter(w => w.length >= 3 && !STOP.has(w));
  return words.length === 0 || words.every(w => srcNorm.includes(w));
};
const TAGS = ['finance', 'markets', 'quant', 'rates', 'tech', 'data', 'ml', 'software', 'python', 'consulting', 'strategy', 'startup', 'product', 'research', 'communication', 'leadership', 'analysis', 'modeling', 'general'];
const tagsOf = t => [...new Set((Array.isArray(t) ? t : String(t || '').split(/[;,]/)).map(x => String(x).trim().toLowerCase()).filter(x => TAGS.includes(x)))].slice(0, 5).join(';') || 'general';
const str = x => (x === null || x === undefined) ? '' : String(x).trim();
const arr = x => Array.isArray(x) ? x : [];

// 3) State: existing ids, next number per prefix
const used = new Set(existing.map(r => r.item_id));
const next = {};
for (const r of existing) {
  const mm = /^([A-Z]+)(\d+)$/.exec(r.item_id);
  if (mm) next[mm[1]] = Math.max(next[mm[1]] || 0, Number(mm[2]));
}
const newId = p => { next[p] = (next[p] || 0) + 1; return p + next[p]; };
const existingTexts = new Set(existing.map(r => norm(r.text)));
const rows = [];
const skipped = [];
const count = { education: 0, experience: 0, project: 0, club: 0, coursework: 0, skill: 0, bullets: 0, profile: 0 };

const push = (item_id, section, parent, text, dates, tags, org, place, role) => {
  rows.push({ chat_id: chatId, item_id, section, parent: parent || '', text, dates: dates || '', tags: tags || '', org: org || '', place: place || '', role: role || '' });
};
const findParent = (section, org) => existing.find(r => r.section === section && norm(r.org) === norm(org));
const bulletCount = {};

function addBullets(parentId, bulletSection, bullets, tagsStr) {
  for (const b of arr(bullets)) {
    const t = str(b);
    if (!t) continue;
    if (!numbersOk(t)) { skipped.push('a bullet with a number I could not find in your CV'); continue; }
    if (existingTexts.has(norm(t)) || rows.some(r => norm(r.text) === norm(t))) continue;
    if (bulletCount[parentId] === undefined) {
      const own = existing.filter(r => r.parent === parentId).map(r => Number((/-(\d+)$/.exec(r.item_id) || [0, 0])[1]));
      bulletCount[parentId] = own.length ? Math.max(...own) : 0;
    }
    bulletCount[parentId] += 1;
    push(parentId + '-' + bulletCount[parentId], bulletSection, parentId, t, '', tagsStr, '', '', '');
    count.bullets++;
  }
}

// Entries with org / place / role / dates (+ bullets)
function entries(list, section, bulletSection, prefix, build) {
  for (const x of arr(list)) {
    const b = build(x);
    if (!b.org || !inSource(b.org)) { skipped.push(section + ': ' + (b.org || 'unnamed') + ' (not found in your CV)'); continue; }
    const years = (b.dates.match(/\d{4}/g) || []);
    if (years.some(y => !srcNorm.includes(y))) { skipped.push(section + ': ' + b.org + ' (date not found in your CV)'); continue; }
    const tags = tagsOf(x.tags);
    let parentRow = findParent(section, b.org);
    let id = parentRow ? parentRow.item_id : null;
    if (!id) {
      if (section === 'education' && !existing.some(r => r.section === 'education') && !rows.some(r => r.section === 'education')) {
        id = 'ED1'; used.add('ED1'); next.ED = Math.max(next.ED || 0, 1);
        push(id, section, '', b.text, b.dates, 'fixed', b.org, b.place, b.role);
      } else {
        id = newId(prefix);
        push(id, section, '', b.text, b.dates, tags, b.org, b.place, b.role);
      }
      count[section]++;
    }
    addBullets(id, bulletSection, x.bullets, tags);
  }
}

entries(m.education, 'education', 'education_bullet', 'ED', x => {
  const school = str(x.school), degree = str(x.degree), place = str(x.place), dates = str(x.dates);
  return { org: school.toUpperCase(), place, role: degree, dates, text: [school, degree].filter(Boolean).join(': ') + (dates ? ', ' + dates : '') };
});
entries(m.experience, 'experience', 'experience_bullet', 'X', x => {
  const org = str(x.org), role = str(x.role), place = str(x.place), dates = str(x.dates);
  return { org: org.toUpperCase(), place, role, dates, text: [role, org, place].filter(Boolean).join(', ') };
});
entries(m.projects, 'project', 'project_bullet', 'P', x => {
  const name = str(x.name), kind = str(x.kind), tools = str(x.tools), dates = str(x.dates);
  return { org: name.toUpperCase(), place: kind, role: tools, dates, text: name + (kind ? ' (' + kind.toLowerCase() + ')' : '') };
});

// Clubs, coursework, skills: one row each
for (const c of arr(m.clubs)) {
  const t = str(c.text), dates = str(c.dates);
  if (!t) continue;
  if (!numbersOk(t)) { skipped.push('club: a number I could not find in your CV'); continue; }
  if (existingTexts.has(norm(t))) continue;
  push(newId('C'), 'club', '', t, dates, tagsOf(c.tags), '', '', ''); count.club++;
}
for (const c of arr(m.coursework)) {
  const t = str(c);
  if (!t || existingTexts.has(norm(t))) continue;
  if (!inSource(t)) { skipped.push('course: ' + t + ' (not found in your CV)'); continue; }
  push(newId('K'), 'coursework', '', t, '', 'general', '', '', ''); count.coursework++;
}
for (const sk of arr(m.skills)) {
  const t = str(sk.text || sk);
  if (!t || existingTexts.has(norm(t))) continue;
  const words = norm(t).replace(/^[^:]*:/, '').split(' ').filter(w => w.length >= 3 && !STOP.has(w));
  const missing = words.filter(w => !srcNorm.includes(w));
  if (missing.length > 1) { skipped.push('skills: ' + t.slice(0, 40) + ' (not found in your CV)'); continue; }
  push(newId('S'), 'skill', '', t, '', tagsOf(sk.tags), '', '', ''); count.skill++;
}

// Profile (name / contact): kept once, only if found in the source
{
  const prof = m.profile || {};
  const digits = x => String(x || '').replace(/\D/g, '');
  const lowSrc = source.toLowerCase();
  const okp = {
    name: v => inSource(v),
    email: v => lowSrc.includes(v.toLowerCase()),
    phone: v => digits(v).length >= 8 && digits(source).includes(digits(v)),
    linkedin: v => lowSrc.includes(v.toLowerCase().replace(/^https?:\/\/(www\.)?/, '').replace(/\/$/, ''))
  };
  for (const key of ['name', 'email', 'phone', 'linkedin']) {
    const v = str(prof[key]);
    const id = 'PR_' + key;
    if (!v || existing.some(r => r.item_id === id)) continue;
    if (!okp[key](v)) { skipped.push('contact: ' + key + ' (not found in your CV)'); continue; }
    push(id, 'profile', '', v, '', '', '', '', '');
    count.profile++;
  }
}

// Fixed lines: languages, certifications, interests (kept once)
const fixed = [['languages', 'F1', 'Languages'], ['certifications', 'F2', 'Certifications'], ['interests', 'F3', 'Interests']];
for (const [key, id, label] of fixed) {
  const t = str(m.fixed && m.fixed[key]);
  if (!t || used.has(id) || existing.some(r => r.item_id === id)) continue;
  const text = /^[A-Za-z ]+:/.test(t) ? t : label + ': ' + t;
  if (!numbersOk(text)) { skipped.push(label + ': a number I could not find in your CV'); continue; }
  push(id, 'fixed', '', text, '', 'fixed', '', '', '');
}

if (rows.length === 0) {
  return fail('I could not find anything new to add. If your CV is a scanned image, paste its text instead.');
}

const parts = [];
if (count.education) parts.push(count.education + ' education');
if (count.experience) parts.push(count.experience + ' experiences');
if (count.project) parts.push(count.project + ' projects');
if (count.bullets) parts.push(count.bullets + ' bullet points');
if (count.club) parts.push(count.club + ' activities');
if (count.coursework) parts.push(count.coursework + ' courses');
if (count.skill) parts.push(count.skill + ' skill lines');
if (count.profile) parts.push('your name and contact details');
let summary = 'Saved to your master CV: ' + parts.join(', ') + '.';
if (skipped.length) summary += '\nI left out ' + skipped.length + ' item(s) I could not verify against your document, so nothing is invented.';

return rows.map((r, i) => ({ json: Object.assign({}, r, { _summary: i === 0 ? summary : '' }) }));

let summary = 'Profile updated.';
try { summary = $('Parse master').first().json._summary || summary; } catch (e) {}
return [{ json: { ok: true, summary: String(summary) } }];
